$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$python = Join-Path $root ".venv\Scripts\python.exe"

$modulePath = Join-Path $pkg "ahos\scene_graph.py"
$testPath = Join-Path $pkg "tests\test_scene_graph.py"
$backlogPath = Join-Path $pkg "STUDIO_BACKLOG.json"
$reportPath = Join-Path $pkg "reports\STUDIO-004-scene-shot-asset-graph-proof.json"

$privateRoot = Join-Path $root "runtime\private\animation-studio"
$characterDb = Join-Path $privateRoot "character-memory.db"
$episodeDb = Join-Path $privateRoot "episode-planning.db"
$graphDb = Join-Path $privateRoot "production-graph.db"
$privateGraph = Join-Path $privateRoot "episodes\S01E001\production-graph.local.json"

$patcher = Join-Path $env:TEMP "studio-004-backlog.py"
$proof = Join-Path $env:TEMP "studio-004-proof.py"

Write-Host "=== STUDIO-004 SCENE + SHOT + PROMPT + ASSET GRAPH ==="
Write-Host "PRIVATE PRODUCTION DATA: LOCAL ONLY"
Write-Host "Render calls: 0"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""

if (-not (Test-Path $python)) { throw "Python venv not found." }
if (-not (Test-Path $pkg)) { throw "AHOS package not found." }
if (-not (Test-Path $characterDb)) { throw "Character Bible DB missing." }
if (-not (Test-Path $episodeDb)) { throw "Episode Planning DB missing." }

New-Item -ItemType Directory -Force -Path (Split-Path $reportPath -Parent) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path $privateGraph -Parent) | Out-Null

[IO.File]::WriteAllBytes(
    $modulePath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $testPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $patcher,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $proof,
    [Convert]::FromBase64String("")
)

$old = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg

    Write-Host "Running Scene Graph focused tests..."
    & $python -m pytest tests\test_scene_graph.py -q
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-004 focused tests failed."
    }

    Write-Host "Running full AHOS + Studio regression suite..."
    & $python -m pytest -q
    if ($LASTEXITCODE -ne 0) {
        throw "Full regression suite failed."
    }

    Write-Host "Building private production graph..."
    & $python $proof $characterDb $episodeDb $graphDb $privateGraph $reportPath
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-004 local proof failed."
    }

    & $python $patcher $backlogPath
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-004 backlog update failed."
    }
}
finally {
    Pop-Location
    $env:PYTHONPATH = $old
    Remove-Item $patcher -Force -ErrorAction SilentlyContinue
    Remove-Item $proof -Force -ErrorAction SilentlyContinue
}

# Private production graph stays outside Git.
$repoResolved = [IO.Path]::GetFullPath($ws)
$privateResolved = [IO.Path]::GetFullPath($privateRoot)
if ($privateResolved.StartsWith($repoResolved, [StringComparison]::OrdinalIgnoreCase)) {
    throw "Privacy guard failed: private production data is inside Git repository."
}

git -C $ws add `
    ahos_core/ahos/scene_graph.py `
    ahos_core/tests/test_scene_graph.py `
    ahos_core/STUDIO_BACKLOG.json `
    ahos_core/reports/STUDIO-004-scene-shot-asset-graph-proof.json

$staged = git -C $ws diff --cached --name-only
if ($staged -match "production-graph\.db|production-graph\.local|episode-planning\.db|character-memory\.db") {
    throw "Privacy guard failed: private production graph was staged."
}

if ($staged) {
    git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" `
        commit -m "feat(studio): add scene shot prompt asset graph"
    if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

    git -C $ws push origin HEAD
    if ($LASTEXITCODE -ne 0) { throw "git push failed." }
}

Write-Host ""
Write-Host "=== STUDIO-004 COMPLETE ==="
Write-Host "Story packet -> production graph: PASS"
Write-Host "Scene graph: PASS"
Write-Host "Shot graph + exact timing: PASS"
Write-Host "Character reference assets: PASS"
Write-Host "Environment reference assets: PASS"
Write-Host "Renderer-ready prompt packs: PASS"
Write-Host "Negative prompts / continuity constraints: PASS"
Write-Host "Asset provenance hashes: PASS"
Write-Host "Pending render outputs only: PASS"
Write-Host "Persistent versioned private graph DB: PASS"
Write-Host "Private production data kept OUTSIDE Git: PASS"
Write-Host "Full regression suite: PASS"
Write-Host "Render calls: 0"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""
Write-Host "PRIVATE GRAPH DB: $graphDb"
Write-Host "NEXT: STUDIO-005 visual generation + animation pipeline / ComfyUI adapters."
